    static member Create (property: string, message: string) : ValidationError = jsNative

/// <summary>The package's value exports, each bound to its import.</summary>
[<Erase>]
type Exports =
    /// <summary>
    /// To use the validator call JSONSchema.validate with an instance object and an optional schema object.
    /// If a schema is provided, it will be used to validate. If the instance object refers to a schema (self-validating),
    /// that schema will be used to validate and the schema parameter is not necessary (if both exist,
    /// both validations will occur).
    /// </summary>
    [<Import("validate", "json-schema")>]
    static member validate (instance: obj, schema: U3<JSONSchema4, JSONSchema6, JSONSchema7>) : ValidationResult = jsNative
    /// <summary>
    /// The checkPropertyChange method will check to see if an value can legally be in property with the given schema
    /// This is slightly different than the validate method in that it will fail if the schema is readonly and it will
    /// not check for self-validation, it is assumed that the passed in value is already internally valid.
    /// </summary>
    [<Import("checkPropertyChange", "json-schema")>]
    static member checkPropertyChange (value: obj, schema: U3<JSONSchema4, JSONSchema6, JSONSchema7>, property: string) : ValidationResult = jsNative
    /// <summary>
    /// This checks to ensure that the result is valid and will throw an appropriate error message if it is not.
    /// </summary>
    [<Import("mustBeValid", "json-schema")>]
    static member mustBeValid (result: ValidationResult) : unit = jsNative
